<?php declare(strict_types=1);use yii\helpers\Html;$roles=$directory['roles'];$assigned=array_sum(array_column($roles,'userCount'));$latest='';foreach($roles as$r)$latest=max($latest,$r['updatedAt']);$latestLabel=$latest===''?'Нет данных':(new DateTimeImmutable($latest))->setTimezone(new DateTimeZone('Europe/Moscow'))->format('d.m.Y H:i');$labels=['access.administer'=>'Администрирование','objects.read'=>'Объекты','installers.read'=>'Монтажники','construction_control.read'=>'Стройконтроль','checklist.edit'=>'Чек-лист','otiz.manage'=>'ОТиЗ','management.read'=>'Контроль'];?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Роли · FMonitor 2.0</title><link rel="stylesheet" href="/pilot/assets/shlz.css"><link rel="stylesheet" href="/pilot/assets/pilot.css"><link rel="icon" type="image/svg+xml" href="/pilot/assets/favicon.svg"></head><body class="shlz-scope"><a class="fm2-skip shlz-link" href="#main-content">Перейти к содержанию</a><div class="fm2-shell"><aside class="fm2-sidebar"><div class="fm2-nav-body"><a class="fm2-logo" href="/pilot/objects" aria-label="FMonitor 2.0 — объекты монтажа"><svg class="fm2-logo-mark" viewBox="0 0 32 32" aria-hidden="true"><rect class="fm2-logo-rail" x="5" y="4" width="4" height="24"/><rect class="fm2-logo-rail" x="23" y="4" width="4" height="24"/><rect class="fm2-logo-progress" x="11" y="10" width="10" height="12"/></svg><span class="fm2-logo-name">FMonitor 2.0</span></a><nav class="fm2-primary-nav" aria-label="Основная навигация"><span class="fm2-nav-group">Администрирование</span><a class="fm2-nav-item" href="/pilot/admin/roles" aria-current="page"><span class="fm2-nav-text">Роли</span></a></nav></div><div class="fm2-sidebar-user"><span class="shlz-avatar shlz-avatar--32 fm2-sidebar-avatar" aria-hidden="true"><?=Html::encode(mb_strtoupper(mb_substr($identity->displayName,0,1)))?></span><span class="fm2-sidebar-user-copy"><strong><?=Html::encode($identity->displayName)?></strong><small><?=Html::encode($identity->email)?></small></span><form method="post" action="/pilot/logout" class="fm2-logout-form"><input type="hidden" name="<?=Html::encode(Yii::$app->request->csrfParam)?>" value="<?=Html::encode(Yii::$app->request->csrfToken)?>"><button class="fm2-logout" type="submit"><span class="fm2-logout-text">Выйти</span></button></form></div></aside><div class="fm2-workspace"><main class="fm2-main" id="main-content" tabindex="-1"><div class="fm2-page-header"><div><h1>Роли</h1><p>Роли FMonitor и назначенные им полномочия</p></div><span class="fm2-result-count"><?=count($roles)?> ролей</span></div><section class="fm2-directory-summary fm2-role-summary"><div><strong><?=count($roles)?></strong><span>Всего ролей</span></div><div><strong><?=count(array_filter($roles,static fn($r)=>$r['active']))?></strong><span>Активные</span></div><div><strong><?=$assigned?></strong><span>Назначений</span></div><p><b>Снимок production:</b> <?=Html::encode($latestLabel)?><br><span>Права объединяются для всех назначенных ролей</span></p></section><section class="fm2-role-model-note"><strong>Как вычисляется доступ</strong><p>Пользователь получает объединение полномочий всех назначенных активных ролей. Название роли не участвует в проверке доступа.</p></section><section class="shlz-table-wrap fm2-list-surface fm2-role-surface"><table class="shlz-table fm2-role-table"><thead class="shlz-table__head"><tr class="shlz-table__row"><th class="shlz-table__cell">Роль</th><th class="shlz-table__cell">Полномочия</th><th class="shlz-table__cell">Статус</th><th class="shlz-table__cell shlz-table__cell--numeric">Пользователей</th></tr></thead><tbody><?php foreach($roles as$r):?><tr class="shlz-table__row"><td class="shlz-table__cell"><strong class="fm2-role-name"><?=Html::encode($r['name'])?></strong><small>ID <?=intval($r['id'])?></small></td><td class="shlz-table__cell"><div class="fm2-permission-list"><?php if($r['permissions']===[]):?><span class="shlz-table__empty">Интерактивных прав нет</span><?php else:foreach($r['permissions']as$p):?><span class="shlz-tag fm2-permission-chip"><?=Html::encode($labels[$p]??$p)?></span><?php endforeach;endif?></div></td><td class="shlz-table__cell"><span class="fm2-employment fm2-employment--<?=$r['active']?'active':'dismissed'?>"><?=$r['active']?'Активна':'Архивная'?></span></td><td class="shlz-table__cell shlz-table__cell--numeric"><strong><?=intval($r['userCount'])?></strong></td></tr><?php endforeach?></tbody></table></section></main></div></div><script src="/pilot/assets/navigation.js"></script></body></html>
